// Improved app.js with security best practices

const express = require('express');
const helmet = require('helmet');         // Security headers
const rateLimit = require('express-rate-limit'); // DoS protection
const cors = require('cors');             // CORS configuration

const app = express();

// --- Security Middleware ---

// Set secure HTTP headers (prevents XSS, clickjacking, MIME sniffing, etc.)
app.use(helmet());

// Configure CORS — restrict to known origins in production
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  methods: ['GET'],
}));

// Rate limiting to prevent brute-force/DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// Body parsing with size limits (if you add POST routes later)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// --- Request Validation Middleware ---

// Reject unexpected Content-Types
app.use((req, res, next) => {
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    const contentType = req.headers['content-type'];
    if (contentType && !contentType.includes('application/json')) {
      return res.status(415).json({ error: 'Unsupported Media Type. Use application/json.' });
    }
  }
  next();
});

// --- Routes ---

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res, next) => {
  try {
    // In production, add authentication/authorization checks here
    // e.g., validate JWT, check user roles, etc.

    const users = [
      { id: 1, name: 'Alice' },  // Don't expose emails without auth
      { id: 2, name: 'Bob' },
    ];

    res.json({ data: users, count: users.length });
  } catch (err) {
    next(err); // Forward to global error handler
  }
});

// --- 404 Handler ---
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// --- Global Error Handler ---
// Must have 4 parameters for Express to recognize it as an error handler
app.use((err, req, res, next) => {
  // Log the full error internally (use a proper logger in production)
  console.error(`[${new Date().toISOString()}] Error:`, err.message);

  // Never leak stack traces or internal details to the client
  const statusCode = err.statusCode || 500;
  const message = statusCode === 500
    ? 'An internal server error occurred.'
    : err.message;

  res.status(statusCode).json({ error: message });
});

